function initialize(){
 const root=document.getElementById('scenario'),input=root.querySelector('#usage'),svg=d3.select(root.querySelector('svg')),money=value=>'$'+value.toFixed(2);
 function render(){const units=Number(input.value);if(!Number.isFinite(units)||units<0||units>500)return;const a=20+.08*units,b=5+.20*units;root.querySelector('#usage-value').textContent=units+' units';root.querySelector('#cost-a').textContent=money(a);root.querySelector('#cost-b').textContent=money(b);root.querySelector('#difference').textContent=Math.abs(a-b)<.001?'Both plans cost the same.':(a<b?'Plan A':'Plan B')+' saves '+money(Math.abs(a-b))+' per month.';
 const width=Math.max(280,root.clientWidth),height=270,margin={top:20,right:20,bottom:42,left:48},x=d3.scaleLinear().domain([0,500]).range([margin.left,width-margin.right]),y=d3.scaleLinear().domain([0,110]).nice().range([height-margin.bottom,margin.top]),series=[{name:'Plan A',value:n=>20+.08*n,color:'var(--color-text-info)'},{name:'Plan B',value:n=>5+.20*n,color:'var(--color-text-secondary)'}];svg.attr('viewBox',[0,0,width,height]);svg.selectAll('*').remove();svg.append('g').attr('transform','translate(0,'+(height-margin.bottom)+')').call(d3.axisBottom(x).ticks(width<420?4:6).tickSizeOuter(0));svg.append('g').attr('transform','translate('+margin.left+',0)').call(d3.axisLeft(y).ticks(4).tickFormat(n=>'$'+n).tickSizeOuter(0));svg.append('text').attr('x',width-margin.right).attr('y',height-6).attr('text-anchor','end').text('units / month');svg.append('line').attr('x1',x(units)).attr('x2',x(units)).attr('y1',margin.top).attr('y2',height-margin.bottom).attr('stroke','var(--color-border-primary)').attr('stroke-dasharray','3 4');for(const s of series){svg.append('path').datum(d3.range(0,501,10)).attr('fill','none').attr('stroke',s.color).attr('stroke-width',2).attr('d',d3.line().x(n=>x(n)).y(n=>y(s.value(n))));svg.append('circle').attr('cx',x(units)).attr('cy',y(s.value(units))).attr('r',5).attr('fill',s.color)}}
 input.addEventListener('input',render);root.querySelector('#reset').addEventListener('click',()=>{input.value='100';input.dispatchEvent(new Event('input',{bubbles:true}))});new ResizeObserver(render).observe(root);render();
}
